const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms));
const assert=(v,m)=>{if(!v)throw Error(m);},button=a=>`[data-deck="1"][data-action="${a}"]`;
const click=s=>{assert($(s),'Missing '+s);$(s).click();};
const files=['app.js','engine.js','panels.js','manual-loops.js','beatgrid.js','smart-sync.js','sync-tempo-handoff.js','sampler-sync.js','sample-sync-transport.js','warp-loop.js','warp-loop-kernel.js','warp-loop-worklet.js','stems.js','keylock.js','keylock-worker.js','keylock-dsp.js','track-gain.js','sampler-sync-175-harness.js','stem-activation-capture-145.js','vendor/signalsmith-stretch/SignalsmithStretch-open-play-reference-dsp.mjs'];
const sha=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');
async function identities(){return Object.fromEntries(await Promise.all(files.map(async f=>{const response=await fetch(f,{cache:'no-store'});assert(response.ok,f);return[f,await sha(await response.arrayBuffer())];})));}
async function until(fn,label,ms=30000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function input(selector,value){const el=$(selector);assert(el,selector);if(typeof value==='boolean')el.checked=value;else el.value=String(value);el.dispatchEvent(new Event('input',{bubbles:true}));}
function base64(bytes){let value='';for(let i=0;i<bytes.length;i+=16384)value+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(value);}
let app,readiness;
async function run(){
 clearInterval(readiness);$('#music-run').disabled=true;
 const {state,engine}=app,deck=state.decks[1],phase=new URL(location.href).searchParams.get('phase')||'fresh',witnesses=[];
 const r={checkpoint:150,diagnosticCheckpoint:175,samples:[],phase,startedAt:new Date().toISOString(),criteria:{minimumRMS:1e-5,maximumStoppedPeak:1e-7,maximumClockError:.01,rawRelativeRMS:1e-4},stages:[],errors:[],uiErrors:[],sourceBefore:await identities(),scope:'Actual current/persistent Sampler Sync versus synced leader Play and tempo+6, warped saved loop/keylock; physical muted. Baseline establishes control/tempo/phase gaps; no full parity claim.'};let track,original,zero,zeroStereo;
 const unhandled=event=>{r.uiErrors.push({message:event.reason?.message||String(event.reason),stack:event.reason?.stack});event.preventDefault();};window.addEventListener('unhandledrejection',unhandled);
 function snapshot(){const slot=state.samples[0][0],voice=engine.samples?.get(0);const lead=state.decks[0],lv=engine.voices.get(0);return{leader:{position:engine.position(lead),playing:lead.playing,processing:lead.processing,sync:lead.sync,syncState:lead.syncState,rate:lead.rate,bpm:lead.track.bpm*lead.rate,sourceBPM:lead.track.bpm,grid:lead.track.grid,anchorTime:lead.anchorTime,anchorPosition:lead.anchorPosition,gridBPM:lv?.gridTimeline?.bpm||null},syncControl:!!$('#sample-sync-toggle'),at:engine.ctx.currentTime,slot:{...slot},position:engine.samplePosition(0),voice:voice?{trackId:voice.track.id,settings:{...voice.settings},anchorTime:voice.anchorTime,anchorPosition:voice.anchorPosition,syncBPM:voice.gridTimeline?.bpm||voice.settings.syncBPM||voice.track.bpm*voice.settings.rate,scale:voice.scale,syncTransport:!!voice.syncTransport,sourceLoop:voice.source.loop??null,sourceLoopStart:voice.source.loopStart??null,sourceLoopEnd:voice.source.loopEnd??null,sourceRate:voice.source.playbackRate?.value??null,gain:voice.gain.gain.value,trackGain:voice.trackGain.gain.value,bufferFrames:(voice.source.buffer||voice.audioBuffer).length,bufferRate:(voice.source.buffer||voice.audioBuffer).sampleRate}:null,notice:$('#notice')?.textContent};}
 async function capture(seconds){return Promise.all(witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM timeout')),10000);w.port.onmessage=async({data})=>{if(data.type==='done'){clearTimeout(timer);resolve({channel:w.channel,startFrame:data.startFrame,frames:data.data.length,quanta:data.quanta,errors:data.errors,sha256:await sha(data.data.buffer),base64:base64(new Uint8Array(data.data.buffer))});}};w.port.postMessage({type:'capture',id:'sampler175',frames:Math.round(seconds*engine.ctx.sampleRate)});})))}
 async function seek(p){$('[data-seek="1"]').dispatchEvent(new KeyboardEvent('keydown',{key:'Home',bubbles:true}));await until(()=>engine.position(deck)===0&&!deck.processing,'Seek Home');for(let n=1;n<=p;n++){$('[data-seek="1"]').dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));await until(()=>engine.position(deck)===n&&!deck.processing,'Seek '+n);}}
 try{
  r.context={sampleRate:engine.ctx.sampleRate,constructor:engine.ctx.constructor.name,requestedSampleRate:null};await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical mute');
  track=state.tracks.find(t=>t.contentHash==='cb2e756d1fa4ce264767a4f6adbaf9e3f69a040db7889d830abdb429cc1a5ac3');assert(track,'Expected imported/restored track');await until(()=>!state.analysis,'Analysis');
  const file=track.file||await track.readFile();r.inputFile={sha256:await sha(await file.arrayBuffer()),bytes:file.size,filename:file.name,hasDirectFile:!!track.file,storage:track.storage};assert(r.inputFile.sha256===track.contentHash&&file.size===167100,'Exact file');
  click(`[data-track="${track.id}"]`);click(button('load'));await until(()=>deck.track===track&&!deck.processing,'Load');original=await engine.buffer(track);r.input={frames:original.length,sampleRate:original.sampleRate,channels:original.numberOfChannels};r.inputPCM=await Promise.all([0,1].map(async channel=>{const bytes=new Uint8Array(original.getChannelData(channel).buffer);return{channel,sha256:await sha(bytes),base64:base64(bytes)};}));
  if(phase==='fresh'){
   assert(!track.savedLoops.some(Boolean)&&!track.cues.some(Boolean),'Fresh track metadata');
   click(button('grid'));$('#grid-bpm').value='120';$('#grid-offset').value='0';click('#grid-clear');for(const m of [{time:1,bpm:150},{time:1.8,bpm:90}]){$('#grid-warp-time').value=m.time;$('#grid-warp-bpm').value=m.bpm;click('#grid-marker');}click('#grid-save');await until(()=>!$('#modal').open,'Save grid');
   await seek(1);click(button('loopIn'));await sleep(20);await seek(3);click(button('loopOut'));await until(()=>deck.loop&&!deck.processing,'Manual Loop Out');
   click(button('tab')+'[data-tab="Loops"]');await until(()=>deck.tab==='Loops','Loops tab');click(button('pad')+'[data-pad="1"]');await until(()=>track.savedLoops[1],'Save loop slot2');
   click(button('loop'));await until(()=>!deck.loop&&!deck.processing,'Loop off');click(button('tab')+'[data-tab="Cues"]');await seek(2);$(button('pad')+'[data-pad="2"]').dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));await until(()=>track.cues[2],'Cue slot3');document.dispatchEvent(new KeyboardEvent('keyup',{key:'Enter',bubbles:true}));await until(()=>!deck.playing&&!deck.processing,'Cue released');
  }else assert(phase==='restored'&&!r.inputFile.hasDirectFile&&r.inputFile.storage==='saved','Normal restored library/readFile');
  r.metadata={loopKeys:Object.keys(track.savedLoops),loops:Array.from(track.savedLoops,l=>l||null),cueKeys:Object.keys(track.cues),cues:Array.from(track.cues,c=>c||null),grid:{bpm:track.bpm,offset:track.grid,markers:track.gridWarpMarkers}};
  r.persistedMetadata=JSON.parse(localStorage.getItem('openplay-review-v1')).localTags[track.contentHash];
  click('[data-panel="sampler"]');await until(()=>$('#sampler-output'),'Sampler panel');click('[data-sample="0:load"]');await until(()=>state.samples[0][0].track===track.id,'Sample Load');
  click('[data-panel="settings"]');const syncSetting=$('[data-setting="Sync Mode"]');syncSetting.value='Smart Sync';syncSetting.dispatchEvent(new Event('change',{bubbles:true}));click('#save-settings');
  click('[data-deck="0"][data-action="sync"]');await until(()=>state.decks[0].sync&&!state.decks[0].processing,'Leader Sync');click('[data-deck="0"][data-action="play"]');await until(()=>state.decks[0].playing&&!state.decks[0].processing,'Leader Play');
  click('[data-sample="0:advanced"]');await until(()=>$('#sample-from'),'Advanced');r.options=[...$('#sample-from').options].map(o=>({value:o.value,text:o.textContent}));input('#sample-from','loop:1');input('#sample-gain',0);input('#sample-volume',80);input('#sample-pitch',0);input('#sample-keylock',true);
  r.persistentSyncControlPresent=!!$('#sample-sync-toggle');if(r.persistentSyncControlPresent)click('#sample-sync-toggle');else click('#sample-sync');click('#sample-apply');
  const repeat=$('[data-sample-repeat="0"]');if(!repeat.checked)repeat.click();
  await engine.ctx.audioWorklet.addModule(new URL('./stem-activation-capture-145.js',import.meta.url));const split=engine.ctx.createChannelSplitter(2);zero=engine.ctx.createConstantSource();zero.offset.value=0;zeroStereo=engine.ctx.createChannelMerger(2);zero.connect(zeroStereo,0,0);zero.connect(zeroStereo,0,1);zeroStereo.connect(engine.samplerOutput);zero.start();r.witnessZeroKeepAlive={offset:0,channels:2};engine.samplerOutput.connect(split);for(let c=0;c<2;c++){const w=new AudioWorkletNode(engine.ctx,'open-play-stem-activation-145-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});w.channel=c;split.connect(w,c);w.connect(engine.ctx.destination);witnesses.push(w);}
  click('[data-sample="0:play"]');await until(()=>state.samples[0][0].playing&&!state.samples[0][0].processing&&engine.ctx.currentTime>engine.samples.get(0).anchorTime+.04,'Sample Play');
  for(const name of ['initial-sync','leader-tempo-change']){
   if(name==='leader-tempo-change'){input('[data-tempo="0"]',6);await until(()=>Math.abs(state.decks[0].rate-1.06)<1e-8&&!state.decks[0].processing,'Leader tempo');await sleep(300);}
   const row={name,after:snapshot(),clockSamples:[]};r.stages.push(row);const clock=setInterval(()=>row.clockSamples.push(snapshot()),10);try{row.pcm=await capture(3);}finally{clearInterval(clock);}row.last=snapshot();
  }
  click('[data-sample="0:stop"]');await until(()=>!engine.samples?.has(0),'Sample Stop');await sleep(1000);r.stages.push({name:'stop',after:snapshot(),pcm:await capture(.3)});
  r.originalUnchanged=(await Promise.all([0,1].map(c=>sha(original.getChannelData(c).buffer)))).every((h,i)=>h===r.inputPCM[i].sha256);r.inputFileUnchanged=await sha(await file.arrayBuffer())===r.inputFile.sha256;assert(r.originalUnchanged&&r.inputFileUnchanged,'Original media changed');r.workflowExecuted=true;
 }catch(error){r.errors.push({message:error.message,stack:error.stack});r.failureState={sample:snapshot(),body:document.body.innerText.slice(-1200)};}
 finally{
  engine.stopAllSamples();if(zero){zero.stop();zero.disconnect();zeroStereo.disconnect();}for(const d of state.decks)engine.pause(d);for(const w of witnesses){w.disconnect();w.port.close();}window.removeEventListener('unhandledrejection',unhandled);r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.workflowCompleted=!!r.workflowExecuted&&!r.errors.length&&!r.uiErrors.length&&r.sourceStable;r.finishedAt=new Date().toISOString();const raw=JSON.stringify(r),id=crypto.randomUUID().replaceAll('-','');let receipt;
  try{const response=await fetch('/api/test-evidence/stem-resource-150/'+id,{method:'POST',headers:{'Content-Type':'application/json','X-Open-Play':'local-prototype'},body:raw});assert(response.ok,'Save original');receipt=await response.json();assert(receipt.bytes===new TextEncoder().encode(raw).length&&receipt.sha256===await sha(new TextEncoder().encode(raw)),'Receipt mismatch');}catch(error){receipt={id,error:error.message};}
  const summary={phase,workflowCompleted:r.workflowCompleted,sourceStable:r.sourceStable,context:r.context,inputFile:r.inputFile,metadata:r.metadata,advancedOpened:r.advancedOpened,options:r.options,persistentSyncControlPresent:r.persistentSyncControlPresent,stages:r.stages.map(({pcm,clockSamples,...s})=>({...s,clockSampleCount:clockSamples?.length})),errors:r.errors,uiErrors:r.uiErrors,receipt};$('#music-original').textContent=JSON.stringify(summary);$('#music-results').textContent=JSON.stringify(summary,null,2);$('#music-status').textContent=r.workflowCompleted?'Sampler Sync recorded; independent inspection pending':'Failed workflow retained';
 }
}
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'App');app=window.openPlay;app.engine.init();app.engine.audioMonitor.mutePhysical(true);$('#music-status').textContent='Import the private research MP3, or use the normally restored library';readiness=setInterval(()=>{if(app.state.tracks.some(t=>t.contentHash==='cb2e756d1fa4ce264767a4f6adbaf9e3f69a040db7889d830abdb429cc1a5ac3')){$('#music-run').disabled=false;$('#music-status').textContent='Imported/restored track ready';}},250);}
$('#music-run').onclick=()=>run();boot().catch(error=>$('#music-status').textContent=error.message);
